      </fieldset></section>`;
  };

  const body = `<a class="skip" href="#review">Skip to review</a>
<header class="top"><div class="wrap">
  <div class="row"><h1>Review revival batch</h1>${dataLabel ? `<span class="banner">${esc(dataLabel)}</span>` : ''}</div>
